-- Rifts World Book 9: South America 2 - its bestiary and its notable NPCs.
-- 15 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~087-south-america-2-race-creatures.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.



-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 15 creatures are in' AS assertion, count(*) AS got, 15 AS want
  FROM creatures WHERE slug IN ('true-inca', 'pucara-red-giant', 'arkhon', 'fallam', 'ojahee', 'men-rall', 'blood-lizard', 'serpentoid', 'mutant-capybara', 'equinoid', 'condoroid', 'falconoid', 'neo-human', 'amaki-stone-man', 'larhold-barbarian');
SELECT 'and 15 of them are playable' AS assertion, count(*) AS got, 15 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('true-inca', 'pucara-red-giant', 'arkhon', 'fallam', 'ojahee', 'men-rall', 'blood-lizard', 'serpentoid', 'mutant-capybara', 'equinoid', 'condoroid', 'falconoid', 'neo-human', 'amaki-stone-man', 'larhold-barbarian');
SELECT 'the creatures carry 27 attacks' AS assertion, count(*) AS got, 27 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('true-inca', 'pucara-red-giant', 'arkhon', 'fallam', 'ojahee', 'men-rall', 'blood-lizard', 'serpentoid', 'mutant-capybara', 'equinoid', 'condoroid', 'falconoid', 'neo-human', 'amaki-stone-man', 'larhold-barbarian');

