INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('true-inca', 'True Inca', 'supernatural', 'rifts', 1, 'Any, but most are good or Unprincipled', '{"IQ":"3D6+4","ME":"3D6+4","MA":"3D6+6","PS":"4D6+6","PP":"3D6+5","PE":"3D6+10","PB":"3D6+6","Spd":"4D6+8"}', NULL, NULL, 'PEx8', '2D6x10+PE', '2D4x10+ME', 'M.D.C. is P.E. x8, plus the P.E. number again at each additional level (the book''s example: P.E. 18 is 144 M.D.C. at level one and 18 more per level); S.D.C. bonuses from physical skills count as M.D.C. P.P.E. is 2D6x10 plus P.E., +15 per level, ONLY for a practitioner of magic; otherwise it is 1D4x10. I.S.P. (every True Inca with psionics) is 2D4x10 plus M.E., +2D6 per level. Patron adjustments: Viracocha +1D6x10 M.D.C. and +6 P.S.; Inti +10 M.D.C. and +2 P.P.; Pachamama +3 M.A. and +3 P.E.; Illapa +2 P.S. and +2 P.P. Supernatural P.S.', NULL, 10, '{"strike":1,"parry":1,"dodge":1}', '+1D4 on initiative, +2 to save vs magic, +6 to save vs Horror Factor. Magic users add one attack/action per melee. Horror Factor 10 applies only once the true nature is revealed. Combat as per Hand to Hand skill; damage is Supernatural P.S. or by weapon or power. Vulnerabilities: none.', 'R.C.C. skills: Dragonese/Elven 98%, Quechua 98%, Spanish 98%, one language of choice (+20%), Demon and Monster Lore (+20%), Basic Math (+10%), Wilderness Survival (+15%), two W.P.s of choice, Hand to Hand: Expert (Martial Arts for one other skill). Eight other skills, plus two more at levels 3, 7, 10 and 14; five secondary skills.', 'Sees the invisible, has nightvision to 200 feet (61 m), and regenerates 1D4x10 M.D.C. a minute. Everything else comes from the patron god. Viracocha: exorcism at 60% +3% per added level, and no possession or mind control can take hold. Inti: flight to 300 mph (480 kmph), a 20 foot (6.1 m) halo of real sunlight that hurts vampires at half the usual rate, a personal energy field worth 20 M.D.C. per level, and sun-bolts. Pachamama: six free healings a day, each mending 2D6 M.D.C. or 3D6 S.D.C./Hit Points, and her psionic and spell healing mend M.D.C. too. Illapa: flight to Mach One, the warlock storm summoning three times daily, and lightning bolts.', 'By patron. Viracocha: 4 spells each from levels 1-3 at first level, +2 of own level or lower per added level. Pachamama: 3 earth warlock spells each from levels 1-3, +1 per added level. Illapa: 3 water warlock spells each from levels 1-3, +2 per level. Inti: none listed.', 'By patron. Viracocha: 4 sensitive powers, +2 sensitive or healing per level. Inti: the Burster powers Extinguish Flame and Sense Fire. Pachamama: 4 sensitive, 4 healing and 2 physical, +1 from those categories per added level, plus Healing Touch. Illapa: Hydrokinesis and 4 powers from the three non-super categories, +1 per added level.', 'Average six feet (1.8 m) tall', NULL, '40,000+ years, effectively immortal', 'The Empire of the Sun in the Andes, serving as guardians, judges and commanders, usually alone or in groups of no more than four or five; renegades and wanderers roam the Megaverse', 'Any member of the Inca Empire (Inca Warriors, Line Makers, Rune Warriors); godlings and demigods of other pantheons of light, Cosmo-Knights, Undead Slayers, Cyber-Knights and other champions of good', 'The Arkhons, whose Spectral Hunters are sent to destroy them', 'A full R.C.C. with its own skills; player characters begin at level one or two, NPCs average 1D4+2. Issued a magic club (2D4 M.D. on top of Supernatural hand to hand damage), an enchanted spear (2D6 M.D. likewise), one energy weapon, two archaic weapons, enchanted cloth armor of 90 M.D.C. and 1D4x1000 credits in coin. One still serving the Pantheon is given a holy item at level three and further holy weapons at levels five, six and nine.', 'Demigods of the Pantheon of the Sun: tall, athletic, somewhat pale-skinned humanoids in bright tunics, capes and heavy earrings, who founded the Inca Empire centuries before the Rifts. Each owes its powers to one patron deity (Viracocha, Inti, Pachamama or Illapa).', 'Rifts World Book 9: South America 2 p.20-23'),
('pucara-red-giant', 'Pucara Red Giant', 'giant', 'rifts', 1, 'Any, but most revenge-minded Pucara are Aberrant, Miscreant or Diabolic', '{"IQ":"3D4+8","ME":"3D4+12","MA":"3D6","PS":"4D6+24","PP":"3D6","PE":"3D6+10","PB":"2D6","Spd":"2D4x10"}', NULL, NULL, '1D6x100+PE', '2D4+4', '2D6x10+ME', 'M.D.C. is 1D6x100 plus the P.E. number, +10 per level of experience. I.S.P. is 2D6x10 plus the M.E. number, +3D6 per level. Supernatural P.S. Heals 4D6 M.D.C. per hour of rest.', NULL, 11, NULL, '+4 to save vs magic, +5 to save vs Horror Factor, both in addition to attribute and skill bonuses. Combat as per Hand to Hand skill; damage as per Supernatural P.S. Vulnerabilities: none, but in a low-P.P.E. environment on another world the psionic and natural powers drop by 25%.', 'R.C.C. skills: Language and Literacy: Pucara (98%), one language of choice (+15%), Basic Math (+15%), Climbing (+10%), Detect Concealment (+10%), W.P. Blunt, W.P. Sword, two W.P.s of choice, Hand to Hand: Expert (Martial Arts or Assassin for one other skill). Eight other skills, plus one more at levels 3, 5, 7, 10, 12 and 14; six secondary skills.', 'Sees in total darkness and in infrared out to 2000 feet (610 m). Needs neither air nor food, living off ambient P.P.E., so water and vacuum do it no harm. Cannot be possessed or mind controlled and shrugs off much magic. Stone Powers: for 10 I.S.P. it remolds 20 pounds (9 kg) or two feet (0.6 m) of rock per level, about a minute per 20 pounds; for 30 I.S.P. the same amount turns semi-liquid at once, and anyone standing on it sinks unless a dodge of 16 or better is rolled, then is held when it sets until 10 M.D. is done to the rock. A giant sealed into a rock face this way is found only by Detect Ambush at -50%. Strengthen Molecular Bonds: 30 I.S.P. and 1D6 hours a pound (0.45 kg) turns plain stone into an M.D.C. material that takes an edge; all Pucara arms, armor and strongholds are made so.', 'None, and never learns any', 'Master psionic. Two powers from each of the sensitive, physical and healing categories, plus one more from any of those three at each level after the first. The stone powers stand in for super-psionics.', '20 to 24 feet (6.1 to 7.2 m)', '3,000-4,000 pounds', 'Average of 600 years; under 1% live ten or twenty times that long (some past 10,000 years) and are sterile after their first 800 years', 'Hidden strongholds in the highest peaks of the Andes and a vast underground refuge; about 200,000 spread over several dozen small kingdoms in Peru and southern South America', 'None at this time', 'Humans above all, the Nazca and the Empire of the Sun first; also raids the Arkhons, the Megaversal Legion, Santiago and Cordoba, and kills D-Bees who side with humans', 'A full R.C.C. with its own skills; player characters begin at level one or two, NPCs average 1D4+2. The race also has the Pucara Mind Mage O.C.C. Typical arms are a giant stone axe (3D6 M.D. plus P.S. damage) or hammer (4D6 M.D. plus P.S. damage); 40% also carry one captured energy weapon with 1D4 spare E-clips. Armor is solid stone plate (150 M.D.C.) or half plate (90 M.D.C.).', 'Hairless scarlet giants with six narrow eyes set in an arc across a thin, skull-like face studded with knobs and spines. Native to Earth and older in the Andes than any human people, they were driven underground by the Nazca thousands of years ago and most now want revenge, though some only want to be left alone and a few seek friends on the surface.', 'Rifts World Book 9: South America 2 p.52-55'),
('arkhon', 'Arkhon', 'humanoid', 'rifts', 1, 'Any; 65% of the invaders are Anarchist or evil (typically Miscreant or Aberrant)', '{"IQ":"2D6+6","ME":"3D6","MA":"3D6","PS":"2D6+12","PP":"2D6+12","PE":"3D6+4","PB":"3D6+6","Spd":"3D6+10"}', NULL, '2D6x10', NULL, NULL, NULL, 'S.D.C. is 2D6x10 in addition to skill bonuses. Hit Points and P.P.E. are printed only as ''standard, same as humans'', with no formula, so both are left empty here. M.D.C. by armor only. I.S.P. is not printed.', NULL, NULL, '{"initiative":1,"roll":2,"pull_punch":2}', '+2 to save vs magic, +3 to save vs Horror Factor; all in addition to skill and attribute bonuses. Combat by Hand to Hand skill. Humidity of 60% or more: -4 to initiative, -2 to all combat actions and one attack per melee lost, unless in environmental armor. Horror Factor: none.', 'R.C.C. skills: Language and Literacy: Arkhon (98%), two languages of choice (+15%), Computer Operation (+15%), Basic Radio (+15%), Running, one Pilot skill of choice (+10%), W.P. Energy Rifle, W.P. Energy Pistol, W.P. Sword or W.P. Knife, Hand to Hand: Expert (Martial Arts for one other skill). Eight other skills, plus one at levels 3, 5, 8, 11 and 14; five secondary skills.', 'No special abilities; the senses are about as sharp as a human''s.', 'None. The culture gave magic up millennia ago and does not believe in it', 'More common than in humans: 01-18% major, 19-50% minor, 51-56% master. Master psionics become Arkhon ESP Specialists', '5-7 feet (1.5 to 2.1 m)', '120 to 200 lbs. (54 to 90 kg)', '200 years with advanced medicine, half that without; the rich have stretched it by as much as 500 years', 'The Arkhon Freehold in the Andes; prefers high, thin mountain air and shuns humid jungle. A few outcasts have settled in the far south', 'The Fallam, a client race conquered centuries ago, and a few human and D-Bee servants', NULL, 'A full R.C.C. with its own skills. The race also has the Spectral Hunter and ESP Specialist O.C.C.s. Starts with an Arkhon energy rifle and pistol, combat armor, communicator, survival kit and knife, one archaic or modern weapon, and 1D6x1000 Arkhon credits (good only inside the Freehold); a renegade living outside it may hold 2D6x100 standard credits.', 'Slender, wiry aliens that mix cat and reptile features: hairless yellow-grey skin, large pointed ears, a slight crouch and human-looking eyes. Theirs is a warrior culture in which winning and obedience are everything, and the exiled Tlo-Arkhon clan is desperate to wipe out the shame of its defeat.', 'Rifts World Book 9: South America 2 p.71-73'),
('fallam', 'Fallam', 'humanoid', 'rifts', 1, 'Any, although most are evil; 50% are Aberrant and wholly loyal to the Arkhons', '{"IQ":"3D6","ME":"3D6","MA":"3D6","PS":"4D6+16","PP":"2D6+6","PE":"2D6+16","PB":"2D4","Spd":"3D6+6"}', NULL, NULL, 'PEx3', '3D6', NULL, 'M.D.C. is P.E. x3, plus 2D4 per level of experience; S.D.C. bonuses from physical skills are added as M.D.C. Supernatural P.S. I.S.P. is not printed (psionics as for humans).', NULL, 8, '{"initiative":2,"strike":1,"parry":1,"dodge":2,"roll":2,"pull_punch":3}', '+1 to save vs poison and disease, +4 to save vs Horror Factor; all in addition to skill and attribute bonuses. Combat by Hand to Hand skill; damage is Supernatural P.S. Vulnerabilities: none.', 'R.C.C. skills: Basic Radio (+15%), Language and Literacy: Arkhon (98%), Language and Literacy in one Earth language (+15%), three specialty skills from one field (Electrical, Mechanical, Military, Pilot/Pilot Related, Science or Technical; +15% each), two related skills (+10%), W.P. Energy Rifle, W.P. Assault Rifle, Hand to Hand: Basic (Expert for one other skill, Martial Arts or Assassin for two). Ten other skills, plus two at level 3 and one at levels 6, 8, 11 and 14; six secondary skills. The Fallam tongue itself is all but dead.', 'Mends three times as fast as a human, about 18 M.D.C. a day.', 'None', 'Standard, same as humans', 'Average 8 feet (2.4 m) tall', 'Average 400 lbs (180 kg)', '150 years', 'The Arkhon Freehold in the Andes, about 120,000 strong; 32 renegades hide in a D-Bee village in Tolkeen', 'The Arkhons, whose client race they are; no others on Earth', 'Humans in general; renegades are distrusted or hunted by the peoples of South America', 'A full R.C.C. with its own skills; player characters begin at level one or two, NPCs average 1D4+1. The Fallam Battlemaster O.C.C. (3% of the race) is the race''s own. Carries a TB-Prime or FR-5 rifle and one energy weapon of choice, and wears modified Arkhon Body Armor of 110 M.D.C. No cybernetics.', 'Giant minor Mega-Damage aliens with very broad shoulders, a narrow waist and short legs, red-brown skin, tufts of white or pale yellow hair, and a fin flanked by two bony ridges down the back of the neck. Once a peaceful forest people, centuries under the Arkhons have made them as warlike as their masters.', 'Rifts World Book 9: South America 2 p.76-77'),
('ojahee', 'Ojahee', 'humanoid', 'rifts', 1, 'Any', '{"IQ":"3D6","ME":"3D6","MA":"3D6","PS":"2D6+18","PP":"3D6","PE":"3D6+10","PB":"2D6","Spd":"5D6"}', NULL, NULL, 'PEx5', '3D6', NULL, 'M.D.C. is P.E. x5, +10 per level of experience. Supernatural strength and endurance. Recovers 1D6 M.D.C. every 10 minutes. I.S.P. is not printed.', NULL, 8, NULL, '+2 to save vs Horror Factor, +10% to save vs coma/death. Combat as per Hand to Hand skill, with one additional hand to hand attack at level one. Damage as per Supernatural strength. Vulnerabilities: none.', 'Megaversal Trooper (Ojahee) R.C.C. skills: Language: Dakir (98%), native tongue (98%), one language of choice (+10%), Basic Radio (+15%), Detect Ambush (+10%), W.P. Energy Rifle, W.P. Energy Pistol, W.P. Axe (treat as W.P. Blunt), Hand to Hand: Expert (Martial Arts for one other skill). Six other skills, plus one at levels 3, 6, 8, 11 and 13; six secondary skills.', 'Heals quickly, getting back 1D6 M.D.C. each ten minutes.', 'None; the Ojahee distrust magic and rely on technology', 'Very rare: only 1% have any, and of those 80% are minor and 20% major. Master psionics are unheard of', '7-8 feet (2.1 to 2.4 m)', NULL, '90 years; M-Troopers with bionic replacements and cloning treatments may reach 300-400', 'With the Megaversal Legion in South America; native to a Mega-Damage dimension rich in P.P.E.', 'The Megaversal Legion; few others. They look on humans as kindred ''little cousins''', NULL, 'A full R.C.C. whose skill program is the Megaversal Trooper''s; player characters begin at level one or two, NPCs average 2D4+1. Standard issue is Mark II body armor, a plasma rifle (HRP-1) or an inertia rifle (HIAR-22), a further energy weapon, four E-clips or magazines apiece, and a knife, field kit and first-aid kit. Pay is 2000 credits a month plus 800 hazard pay in combat; starts with one month''s pay.', 'Big Mega-Damage soldiers from a world just entering its industrial age, carried off as a whole rifle regiment to serve as shock troops. They prize courage, inventiveness and honor.', 'Rifts World Book 9: South America 2 p.106-107'),
('men-rall', 'Men-Rall', 'alien', 'rifts', 1, 'Any, but lean towards good and selfish', '{"IQ":"2D4+18","ME":"3D6","MA":"3D6","PS":"2D6","PP":"3D6","PE":"3D6","PB":"2D4","Spd":"3D4"}', NULL, NULL, '1D4x10', '3D6', NULL, 'M.D.C. is 1D4x10, +1D6 per level of experience. I.S.P. is NOT printed, although the race is a major psionic with six powers.', NULL, 7, '{"initiative":1}', '+1 to save vs disease, +2 to save vs Horror Factor. Combat as per Hand to Hand skill; the Damage line reads ''as per supernatural P.S.''. Vulnerabilities: none.', 'R.C.C. skills: three languages of choice (+20%), Basic and Advanced Math (+20%), two Science skills of choice (+15%), two Electrical or Mechanical skills of choice (+15%), one W.P. of choice, Hand to Hand: Basic (Expert for one other skill, Martial Arts for two). Ten other skills, at least four of them Science, Electrical, Mechanical or Medical, plus two at level 3, two at level 5 and one at levels 8, 10 and 12; two secondary skills at each of levels 1, 4, 8 and 12. Mecha-Kinesis reads any machine at 88%.', 'Speaks and handles the world through electromagnetic emissions, so it needs a translator device to be understood aloud. Mecha-Kinesis: grasps how any machine works on instinct (88%), for good once it has studied the thing for 1D6 hours, and with ten minutes of touch and concentration repairs 3D6 M.D.C. or 1D6x10 S.D.C. of it, or wrecks as much; far too slow for a fight and useless on the living. Also throws electrical discharges.', 'None', 'Major psionic: six powers from the sensitive, physical or healing categories', '5 to 6 feet (1.5 to 1.8 m)', '100 to 200 lbs.', '300 years', 'About a thousand serve the Megaversal Legion at Fort Desperado as mechanics, engineers, doctors and researchers; a few hundred work in New Babylon', 'The Megaversal Legion and the people of New Babylon', NULL, 'A full R.C.C. (the Tech Master) with its own skills. Starts with one energy weapon and 1D4 spare clips for it, a hand computer, a camera, a flashlight, tools, a first-aid kit, 3D6x100 credits and 2D4x1000 credits'' worth of salable mechanical devices.', 'An old, nearly extinct race of tinkerers with a cluster of eye-stalks where a head would be, known for wearing lab coats with pride. They repair and run other peoples'' machines but never invent their own, dislike fighting, and joined the Legion after it freed them from brodkil slavery.', 'Rifts World Book 9: South America 2 p.111-112'),
('blood-lizard', 'Blood Lizard', 'monster', 'rifts', 1, 'Most are Aberrant or Anarchist', '{"IQ":"2D4+4","ME":"3D6","MA":"2D6","PS":"2D6+20","PP":"2D6+12","PE":"2D6+14","PB":"2D6","Spd":"1D4x10+100"}', NULL, NULL, '3D6x10+20', '5D6', '1D6x10+10', 'M.D.C. 3D6x10+20 (no per-level gain printed). I.S.P. 1D6x10+10, +2D6 per level of experience. Spd 110 to 140, roughly 75 to 100 mph (120 to 160 kmph). Attributes are supernatural. Bio-regenerates 1D6 M.D.C. every minute.', NULL, 9, '{"attacks":3,"initiative":3,"strike":3,"parry":3,"dodge":3,"roll":1,"pull_punch":1}', '+5 to save vs Horror Factor, +2 to save vs psionics; all in addition to attribute bonuses. Three hand to hand or psionic attacks per melee to start, +1 at levels 5, 9 and 13 (natural skills, no Hand to Hand). Dislikes cold and M.D. fire.', 'R.C.C. skills: Wilderness Survival (+20%), Land Navigation (+20%), Detect Ambush (+10%), Swimming (+20%), Climbing (+10%), Prowl (+5%), one language understood but not spoken (+10%). Track by smell 68%, recognize its rider''s scent 88%, recognize others by scent 38%. Psychic Tracking 40% +3% per level. Four other skills, plus one at levels 4, 9 and 14; two secondary skills. Literacy costs two selections; most technical skills are closed.', 'Exceptional eyesight, nightvision to 1000 feet (305 m), and a nose good enough to trail prey by blood or any strong smell and to know its rider at once. Can hold and fire hand weapons. Talks only by telepathy, which Blood Riders and telepaths or empaths hear clearly; others get gestures or sent images and feelings. Psychic Tracking follows the psychic trace of any living thing it has met: +10% for a supernatural quarry, -1% for each day the trail has aged, 60 feet (18.2 m) range, and 1 I.S.P. per 8 hours that does not come back until it has left off the hunt for a full day.', 'None', 'Master psionic: Empathy, Telepathy, See Aura, See the Invisible, the Blood Rider''s bond with its rider, and Psychic Tracking', '8-10 feet (2.4 to 3.0 m)', '800 to 1200 lbs. (362 to 544 kg)', '50 years', 'The plains of the Silver River Republics, alongside the Blood Riders', 'None besides Blood Riders and the occasional Simvan Monster Rider', NULL, 'Optional player character, at the Game Master''s discretion; average level 1D4+1. No O.C.C.: it fights with natural skills. A rider may hand it a heavy energy rifle or rail gun, and a wealthy one may fit armored barding (A.R. 15, 100 M.D.C., 80,000 credits). It owns little else.', 'A D-Bee predator that looks like a two-legged carnosaur but is faster, stronger and fully intelligent. It will not be ridden like a beast: only a Blood Rider it counts as a friend earns that, and the pair will die for or avenge one another.', 'Rifts World Book 9: South America 2 p.137-138'),
('serpentoid', 'Serpentoid', 'mutant', 'rifts', 1, 'Any, but about 50% are Aberrant', '{"IQ":"3D6+4","ME":"2D6+12","MA":"2D6+10","PS":"2D6+20","PP":"3D6+6","PE":"3D6+6","PB":"3D6","Spd":"4D6"}', 'PEx2', '4D6x10', NULL, '4D6', '2D6x10+ME', 'Hit Points are P.E. x2, +2D6 per level. S.D.C. is 4D6x10 plus any skill bonuses. The printed M.D.C. is the psionic force field''s, not the body''s: M.E. x5, +10 per level of experience, raised for 10 I.S.P. and lasting until depleted or one hour per level. I.S.P. is 2D6x10 plus M.E., +10 per level. P.S. is Supernatural only while the field is up.', NULL, 8, NULL, '+2 to save vs magic and psionics, +5 to save vs Horror Factor. Combat as per Hand to Hand skill. Punches and kicks do Supernatural P.S. damage with the force field up and ordinary S.D.C. damage without it. Horror Factor is higher when the Aura of Fear is used. Vulnerabilities: none.', 'R.C.C. skills (basic military training): Language and Literacy: Spanish (98%), one language of choice (+15%), Basic Math (+15%), Radio: Basic (+15%), Wilderness Survival (+10%), W.P. Energy Rifle, two W.P.s of choice, Hand to Hand: Basic (Expert for one other skill; Martial Arts, or Assassin if evil, for two). Eight other skills, plus two at level 3, two at level 7 and one at levels 10 and 12; six secondary skills.', 'Psionic Force Field (10 I.S.P.): Mega-Damage protection that also lends Supernatural strength for damage and lifting while it holds. Entrancement Gaze (15 I.S.P., eye contact within 100 feet/30.5 m): a target failing a save vs psionics stands frozen for as long as the stare is held; the serpentoid may only walk toward it, and a blow or a third party breaking the line of sight ends it, after which the target still forfeits initiative and one action that round. Aura of Fear (20 I.S.P., 10 feet/3.0 m of radius and one minute per level): everyone inside saves against Horror Factor 14, rising by one at levels 3, 6, 9 and 12 to a cap of 18. Psychic Venom: a cobra-strength bite that can be charged with psychic energy.', 'None', 'Master psionic: Mind Block Auto-Defense, Hypnotic Suggestion, and six powers chosen from the healing, sensitive or physical categories, besides the natural abilities', 'Average 6 feet (1.8 m), not counting the tail, which adds another 4 feet (1.2 m)', 'Average 180 lbs. (81.5 kg)', '100 years', 'The Achilles Republic', 'Other mutant animals work beside them, though their coldness leaves most with few friends outside their own kind (rodents least of all)', NULL, 'A full R.C.C. with its own skills; player characters begin at level one or two, NPCs average 1D6+1. Starts with a Light Striker laser rifle or an Equalizer shotgun, an energy sidearm, four reloads for each, customizable combat armor (75 M.D.C.), a hand radio, a gas mask, a survival kit, a bedroll, rations for a week, survival knife and 3D6x100 credits.', 'A Project Achilles mutant blending human and cobra: lean and wiry, with a hooded snake head and a long neck and tail that look like a serpent grafted along a human spine. Most are coldly detached and feel little pity, yet stay fiercely loyal to those they call friends.', 'Rifts World Book 9: South America 2 p.141-142'),
('mutant-capybara', 'Mutant Capybara', 'mutant', 'rifts', 1, 'Any, but most (70%) are Scrupulous', '{"IQ":"3D6+3","ME":"3D6+8","MA":"3D6+6","PS":"3D6+4","PP":"3D6","PE":"2D6+8","PB":"2D6","Spd":"3D6"}', 'PEx2', '2D6x10', NULL, '2D4', '3D6x10+ME', 'Hit Points are P.E. x2, +1D6 per level of experience. S.D.C. is 2D6x10 plus skill and O.C.C. bonuses. M.D.C. by armor or psionic power only. I.S.P. is 3D6x10 plus M.E., +10 per additional level. Spd is 3D6 running, or 1D4x10 swimming.', NULL, 6, NULL, '+1 to save vs magic, +4 to save vs Horror Factor. Combat as per Hand to Hand skill. Vulnerabilities: none.', 'R.C.C. skills: Language and Literacy: Spanish (98%), two languages of choice (+15%), Radio: Basic (+10%), Demon and Monster Lore (+15%), Wilderness Survival (+5%), Holistic Medicine (+10%), W.P. Energy Rifle, one W.P. of choice, Hand to Hand: Basic (Expert for one other skill, Martial Arts for two). Six other skills, plus two at level 3 and one at levels 5, 8, 11 and 14; four secondary skills.', 'Ley Line Transmission and Phasing: sends messages down a ley line for 2 I.S.P. and teleports along one for 6, under the Ley Line Walker''s limits. Time Warp (25 I.S.P.): doubles or halves the flow of time for itself and/or one person per level within 60 feet (18.3 m) +10 feet (3.0 m) per level, save vs psionics if unwilling; the quickened gain three actions or twice their own (the lesser) with +3 initiative, parry and dodge, the slowed lose half their actions and take -4 initiative and -2 strike, parry and dodge. Dimensional Powers: senses Rifts, ley lines and nexuses within a mile (1.6 km) per level, and a Rift 50 miles (80 km) off from level 3; Rifts home at level 5 (150 I.S.P.); closes Rifts at level 7 (200 I.S.P., 2 gone for good), when four together can also raise a ley line storm (150 I.S.P. each); teleports between dimensions at level 10 (75 I.S.P., +25 per passenger; 89%, 76% or 65% by familiarity).', 'None', 'Two powers from each of the healing, sensitive and physical categories, plus one new power from any category except super at each level after the first, besides the natural abilities', '4 to 6 feet (1.2 to 1.8 m) tall', '150-250 lbs. (68 to 113 kg)', '120 years', 'The Achilles Republic, where many sit in the Animal House or serve as army medics; high-level ones wander other dimensions for years at a time', 'Other mutant animals; respected by Prometheans, Temporal Raiders, True Atlanteans and other dimensional travelers', NULL, 'A full R.C.C. with its own skills; player characters begin at level one or two, NPCs run from 1st to 15th and average 1D6+1. Starts with a Light Striker laser rifle or an Equalizer shotgun, an energy sidearm, four reloads for each, customizable combat armor (75 M.D.C.), a hand radio, a gas mask, a survival kit, a bedroll, rations for a week, herbal first-aid kit, survival knife and 3D4x100 credits.', 'A Project Achilles mutant bred from rat, human and capybara stock: a hardy, strong-swimming rodent folk with a mystical turn of mind and an easygoing, patient outlook. Their rarest gift is bending dimensional energy with the mind.', 'Rifts World Book 9: South America 2 p.142-144'),
('equinoid', 'Equinoid', 'mutant', 'rifts', 1, 'Any', '{"IQ":"3D6","ME":"3D6+6","MA":"3D6","PS":"3D6+18","PP":"3D6+6","PE":"3D6+10","PB":"4D6","Spd":"1D6x10+80"}', 'PEx3', '1D4x100', NULL, '2D6', '2D6x10+10+ME', 'Hit Points are P.E. x3, +2D6 per level of experience. S.D.C. is 1D4x100 plus skill bonuses. The printed M.D.C. is the telekinetic force field''s, not the body''s: 60 M.D.C. +10 per level, raised for 10 I.S.P. and lasting two minutes per level. I.S.P. is 2D6x10+10 plus M.E., +2D6 per level. Spd 90 to 140 running or flying, roughly 60 to 100 mph (96 to 160 kmph).', NULL, 8, '{"initiative":2,"strike":1,"parry":1,"roll":1,"pull_punch":2}', '+1 to save vs magic, +4 to save vs Horror Factor; all in addition to attribute and skill bonuses. Combat as per Hand to Hand skill plus one melee attack per round. A power punch or kick does double damage but counts as two attacks. Too big for small vehicles, motorcycles, power armor or robots, and can pilot only vehicles built for it. Prowl is at -10%.', 'R.C.C. skills: Language and Literacy: Spanish (98%), one language of choice (+15%), Radio: Basic (+10%), Tracking (animals and humans; +10%), Wilderness Survival (+10%), W.P. Archery and Targeting, one W.P. of choice, Hand to Hand: Expert (Martial Arts for one other skill). Eight other skills, plus two at each of levels 3 and 6 and one at levels 8, 10 and 14; three secondary skills at each of levels 1 and 4.', 'Sky Running (10 I.S.P., ten minutes per level): gallops on empty air at ground speed, up to 100 feet (30.5 m) high per level; the same gift gives a 30 foot (9 m) standing leap or 60 feet (18.2 m) at a run. Psi-Bow (15 I.S.P., one minute per level): a bow of mental energy, +2 to strike on top of Archery bonuses. Psionic Force Field: while it is up, bare-handed blows do Mega-Damage.', 'None', 'Six powers from the sensitive or physical categories, with no new powers at higher levels, besides the natural abilities', '8-9 feet (2.4 to 2.7 m) tall, about 5-6 feet at the shoulder of the horse body', '800-1200 lbs. (362 to 544 kg)', '120 years', 'The Achilles Republic; 70% of those aged 16-30 are career soldiers in its army, the rest scouts, messengers and bodyguards', 'Other mutant animals; some befriend Blood Riders and many gauchos despite the rivalry', NULL, 'A full R.C.C. with its own skills; player characters begin at level one or two, NPCs average 1D4+2. Starts with custom barding (90 M.D.C.), one energy weapon with four spare E-clips, a hand radio, a gas mask, a survival kit and knife, a bedroll, rations for a week and 2D6x100 credits.', 'The Psi-Taur: a Project Achilles mutant made from mostly human stock, a centaur in shape with short fur all over and a crest of hair like a mohawk. As swift and strong as a horse, it is trained as a warrior from youth.', 'Rifts World Book 9: South America 2 p.144-146'),
('condoroid', 'Condoroid', 'mutant', 'rifts', 1, 'Any, but 30% are Anarchist and 20% Unprincipled', '{"IQ":"3D6","ME":"3D6+6","MA":"3D4","PS":"3D6+4","PP":"2D6+10","PE":"3D6+8","PB":"2D4","Spd":"3D6"}', 'PEx2', '2D4x10+20', NULL, '2D6', '2D4x10+10+ME', 'Hit Points are P.E. x2, +2D4 per level of experience. S.D.C. is 2D4x10+20. The printed M.D.C. is the psionic force field''s, not the body''s: 30 M.D.C. at level one, +10 per additional level, raised for 10 I.S.P. and lasting until depleted or two minutes per level. I.S.P. is 2D4x10+10 plus M.E., +2D6 per level. Spd 3D6 is on the ground; flying is up to 500 mph (800 kmph).', NULL, 8, NULL, '+1 to strike and +2 to dodge while flying. Combat as per Hand to Hand skill. Vulnerabilities: none.', 'R.C.C. skills: Language and Literacy: Spanish (98%), one language of choice (+15%), Radio: Basic (+10%), Wilderness Survival (+10%), Detect Ambush (+10%), Track Humans and Animals (+10%), W.P. Energy Rifle, one W.P. of choice, Hand to Hand: Expert (Martial Arts or Assassin for one other skill). Six other skills, plus two at level 3 and one at levels 5, 7, 10 and 14; five secondary skills.', 'Psionic Flight: the wings only glide and steer; the mind does the lifting, to about 500 mph (800 kmph). Within 100 feet (30.5 m) of a ley line''s center it can push to Mach 2 for 2 I.S.P. a minute, but only straight ahead. Psionic Invisibility (15 I.S.P., one minute per level): sensor operators roll at -40% to pick it up and the living must save vs psionics to notice it at all. Psionic Force Field as noted under the pools.', 'None', 'Psi-Sword, Psi-Shield and six powers from the physical, sensitive and healing categories, plus one more from any category except super at each new level, besides the natural abilities', '4-6 feet (1.2 to 1.8 m) tall; wingspan typically three times the height', '100-200 lbs. (45 to 90 kg)', '100 years', 'The Achilles Republic, as scouts and commando raiders; bandit communities nest in the mountains', 'Other mutant animals; bandits often work with Larhold barbarians, Arkhon renegades and human or D-Bee outlaws', NULL, 'A full R.C.C. with its own skills; player characters begin at level one or two, NPCs average 1D4+1. Starts with a Light Striker laser rifle or an Equalizer shotgun, an energy sidearm, four reloads for each, customizable combat armor (75 M.D.C.), a hand radio, a gas mask, a survival kit, a bedroll, rations for a week, survival knife and 2D6x100 credits.', 'A Project Achilles birdman bred from the Andean condor: man-sized and feathered, with a condor''s head, wings on the back and separate human arms. Too heavy to fly on wings alone, it flies by telekinesis.', 'Rifts World Book 9: South America 2 p.146-148'),
('falconoid', 'Falconoid', 'mutant', 'rifts', 1, 'Any', '{"IQ":"4D6","ME":"3D6+6","MA":"4D6","PS":"3D6+6","PP":"4D6+6","PE":"3D6+6","PB":"3D6","Spd":"1D6x10"}', 'PEx2', '2D4x100', NULL, '2D6', '2D6x10+ME', 'Hit Points are P.E. x2, +1D6 per level of experience. S.D.C. is 2D4x100. The printed M.D.C. is the force field''s, not the body''s: 80 M.D.C. at level one, +20 per additional level, raised for 15 I.S.P. and lasting two minutes per level. I.S.P. is 2D6x10 plus M.E., +8 per additional level. Spd 1D6x10 is running; flying is up to Mach 2.', NULL, 7, '{"initiative":1,"roll":3,"pull_punch":2}', '+1 to strike and dodge in the air. The +3 is to roll with punch, fall or impact. Combat as per Hand to Hand skill. Vulnerabilities: none.', 'R.C.C. skills: Language and Literacy: Spanish (98%), one language of choice (+15%), Radio: Basic (+10%), Wilderness Survival (+10%), Track Humans and Animals (+10%), W.P. Energy Rifle, two W.P.s of choice, Hand to Hand: Expert (Martial Arts or Assassin for one other skill). Six other skills, plus one at levels 3, 5, 7, 10 and 14; five secondary skills.', 'Psionic Flight to Mach 2, though at top speed only dead straight; it usually cruises at Mach 1 (670 mph/1078 kmph) or below. Psionic Force Field as noted under the pools. Psi-Blasts leave the head or eyes and hurt body and mind together.', 'None', 'Six powers from either the physical or sensitive categories, besides the natural abilities', '5 to 6 feet tall (1.5 to 1.8 m)', '90 to 120 lbs. (41 to 54 kg)', '120 years', 'The Achilles Republic, where they are most of its air defense; a few fly its handful of aircraft', 'Other mutant animals', NULL, 'A full R.C.C. with its own skills; player characters begin at level one or two, NPCs average 1D4+1. Starts with a Light Striker laser rifle or an Equalizer shotgun, an energy sidearm, four reloads for each, customizable combat armor (75 M.D.C.), a hand radio, a gas mask, a survival kit, a bedroll, rations for a week, survival knife and 2D6x100 credits.', 'A Project Achilles birdman bred from falcons to outdo the condoroid as a flying soldier. Light, quick and sharp-witted, it duels aircraft and flying power armor over the plains with bolts of mental force.', 'Rifts World Book 9: South America 2 p.148-149'),
('neo-human', 'Achilles Neo-Human', 'mutant', 'rifts', 1, 'Any', '{"IQ":"3D6+8","ME":"2D6+14","MA":"4D6","PS":"3D6+12","PP":"3D6+6","PE":"3D6+10","PB":"2D6+12","Spd":"5D6"}', 'PEx3', '4D6x10', NULL, '2D6', '1D4x100+ME', 'Hit Points are P.E. x3, +2D6 per level of experience. S.D.C. is 4D6x10. No M.D.C. of its own: under the Supernatural Transformation the S.D.C. and Hit Points become M.D.C. points and P.S. becomes Supernatural. I.S.P. is 1D4x100 plus the M.E. number, +12 per level. The transformation halves the I.S.P. base for its duration (points above half are spent) and trims a further 2 from the base each hour, ending when the base reaches zero.', NULL, 9, '{"initiative":1}', '+1 to save vs magic, +3 to save vs possession and mind control, +6 to save vs Horror Factor. Horror Factor 9 applies once identity and powers are revealed. Combat as per Hand to Hand skill. Vulnerabilities: none.', 'R.C.C. skills: Language and Literacy: Spanish (98%), one language of choice (+15%), Radio: Basic (+10%), Intelligence (+10%), Disguise (+10%), W.P. Energy Rifle, two W.P.s of choice, Hand to Hand: Expert (Martial Arts or Assassin for one other skill). Five other skills, plus one at levels 3, 5, 7, 10 and 14; two secondary skills at each of levels 1, 5 and 10.', 'Supernatural Transformation, as noted under the pools. Hyper-Telekinesis (50 I.S.P.): shifts M.E. x100 pounds (45 kg each) and 100 pounds more per level, out to 100 feet (30.5 m) +50 feet (15.2 m) per level, otherwise as ordinary Telekinesis. Telekinetic Flight (15 I.S.P., two minutes per level): up to 100 mph (160 kmph). Mind-Wave (30 I.S.P., 300 feet/91.4 m, one target, uses two attacks): save vs psionics at -2; a save still leaves a headache (-2 initiative, -10% skills for 2D4 minutes), a failure drops the target to its knees in a blissful daze for 2D4 melee rounds +1 per level, and one jolted out of it early by real injury acts at half attacks, bonuses, speed and skill for 2D4 minutes. Touch of Health (15 I.S.P.): restores 1D6x10 S.D.C. or M.D.C., cures ordinary disease, infection and fractures, and gives +30% to survive a coma.', 'None; their P.P.E. goes into mastering psionics', 'Master psionic. Three powers from each of the four categories, super included, under the Mind Melter''s restrictions; four more (one per category) at level two, three from any category at level three, and two per level after that, besides the natural abilities', 'Slightly taller than humans; average height 6 feet, 6 inches (1.95 m)', 'Average 200 lbs (90 kg)', 'Varies with base I.S.P.: about 100 years plus I.S.P. x3', 'The Achilles Republic, as secret agents, special forces and champions; under 1% of its mutants. A few wander the Megaverse', 'Other mutant animals, mutant capybaras best and serpentoids worst; also Mind Melters, Master Blood Riders, godlings, demigods, True Atlanteans and dragons', NULL, 'A full R.C.C. with its own skills; player characters should begin at first level, NPCs average 1D4+1. Starts with an energy rifle and energy sidearm of choice, four E-clips for each, light human-style body armor (45 to 60 M.D.C.), hand radio, gas mask, survival kit, bedroll, a week of rations, survival knife and 2D6x100 credits.', 'The last and strongest product of Project Achilles: mutants that pass for flawless, tall humans and hide an enormous store of psychic power. Those who stayed with the mutant animals are called Neo-Abels; the Neo-Cains walked away in contempt and nobody knows where they went.', 'Rifts World Book 9: South America 2 p.149-151'),
('amaki-stone-man', 'Amaki (Stone-Man)', 'humanoid', 'rifts', 1, 'Any, but lean towards good and selfish', '{"IQ":"3D6","ME":"3D6+2","MA":"3D6+2","PS":"2D6+12","PP":"3D4+10","PE":"3D6+6","PB":"3D6+2","Spd":"3D6"}', 'PEx10', '3D6x100', NULL, '4D6', NULL, 'Hit Points are P.E. x10, +4D6 per level of experience. S.D.C. is 3D6x100 (the equivalent of 3-18 M.D.C.; 1 M.D.C. equals 100 S.D.C.), so an Amaki survives minor M.D. attacks. No M.D.C. Natural A.R. 16. I.S.P. is not printed (by psionic class).', 16, 6, '{"initiative":1,"parry":1,"dodge":1,"roll":2}', '+2 to save vs Horror Factor. Combat by Hand to Hand skill. Damage Resistance: every non-magical attack, physical or energy, does half damage; magic and psionics do full. Vulnerabilities: none.', 'Known by almost all (95%) adult Amaki on Rifts Earth, in addition to O.C.C. skills: Language: Amaki (98%), Spanish (+20%), W.P. Sword and W.P. Energy Pistol (the pair needed for the Amaki blast sword). Most also have Dance (+15%) and one of Play Musical Instrument or Sing (+10%).', 'Nightvision to 1000 feet (305 m), hearing and sight a shade better than the best human, and wounds that close five times as fast as a human''s. The stone-hard hide halves all damage that is neither magical nor psionic.', 'By O.C.C. Half of Amaki mages are Techno-Wizards; Shifters, Ley Line Walkers and Temporal Mages are 10% each, others 20%', 'More common than in humans: 01-20% major, 21-50% minor, 51-64% master, 65-00% none. Half the master psionics are Mind Melters', '5 to 7 feet tall (1.5 to 2.1 m)', '120 to 200 lb. (54 to 90 kg)', '300 years', 'New Babylon, which they share with humans', 'The humans of New Babylon; on other worlds, a number of True Atlantean clans', NULL, 'A race that takes an O.C.C.; typical NPC level 1D4+1. Common choices: Duelist and Gizmoteer, Headhunter, Wilderness Scout, Rogue Scholar, Operator and City Rat; military O.C.C.s as the Coalition''s, with the odd master assassin, bounty hunter, special forces soldier, smuggler, thief or spy; the mage and psychic classes given under magic and psionics, plus Bursters and the local equals of Psi-Stalkers and Mind Bleeders. Gear is the O.C.C.''s.', 'Aliens who look like statues of ideal humans carved in polished grey or black marble, the men with sculpted chin-growths like Assyrian beards. They love flamboyant dress and body paint, found humans the most kindred people they had ever met, and often marry them.', 'Rifts World Book 9: South America 2 p.154-155'),
('larhold-barbarian', 'Larhold Barbarian', 'humanoid', 'rifts', 1, 'Any, but lean towards Anarchist and evil', '{"IQ":"3D6","ME":"3D6","MA":"3D6","PS":"4D6+12","PP":"3D6+2","PE":"3D6+6","PB":"2D4","Spd":"3D4"}', NULL, NULL, 'PE+2D4x10', '3D6', NULL, 'M.D.C. is the P.E. number plus 2D4x10 (no per-level gain printed). Supernatural P.S. Heals 3D6 M.D.C. per hour of rest. I.S.P. is not printed (psionics as for humans).', NULL, 8, '{"initiative":1,"roll":2,"pull_punch":2}', 'One additional attack per melee, +2 to save vs magic, +6 to save vs Horror Factor; all in addition to skill and attribute bonuses. Horror Factor is 10 where the Larhold reputation is known. Combat as per Hand to Hand skill; damage is Supernatural strength. Vulnerabilities: none.', 'R.C.C. skills: Language: Larhold (98%), one language of choice (+15%), Basic Math (+10%), Riding: War Bison (+20%), Wilderness Survival (+15%), Detect Ambush (+10%), Detect Concealment (+10%), W.P. Archery and Targeting, W.P. Sword, one W.P. of choice, Hand to Hand: Expert (Martial Arts or Assassin for one other skill). Seven other skills, plus two at level 3 and one at levels 6, 9 and 12; six secondary skills. A Larhold in another O.C.C. still has Riding: War Bison (as Horsemanship, +10%) and W.P. Archery and Targeting.', 'Nightvision to 200 feet (61 m) and fast healing.', 'None unless a magic O.C.C. is taken', 'Standard; same as humans', 'Average 6 feet tall (1.8 m)', '200-350 lbs. (90 to 157.5 kg)', '70 years', 'Nomadic tribes ranging the far south of South America, raiding the Achilles Republic, New Babylon and their neighbors', 'Their own tribe and, for a large raid, other tribes; very rarely an alien intelligence, god of darkness or powerful warlord. Priests of the gods of Darkness sometimes help them', NULL, 'A full R.C.C. with its own skills; average level 1D4+2. Other O.C.C.s open to the race: Larhold Shaman, Mystic, Ley Line Walker, Shifter, Witch, Warlock and Temporal Mage, and for strong psychics the Mind Melter and Burster R.C.C.s. Carries the Larhold Composite Bow (hand to hand damage from Supernatural P.S. +6 M.D., 800 feet/244 m, needs Supernatural P.S. 16) and Larhold Saber (2D6 M.D. on top of Supernatural P.S. damage), one energy weapon with 1D4 clips, one modern weapon, hide armor of 70 M.D.C. (-10% to prowl), a War Bison or small vehicle, camp gear and 1D6x1000 credits in cash or trade goods.', 'Stocky, broad-shouldered, bow-legged riders with four small bison-like horns at the temples, braided hair and, on the men, long mustaches and goatees. Supernaturally strong nomads who fight by ambush, feint and terror, they are cruel to captives and to each other but never to children.', 'Rifts World Book 9: South America 2 p.185-186');
INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'true-inca', 'Sun-Bolt (Inti Inca)', '2D6 M.D.', 1, '500 feet (152 m)', 'Inti patron only. +1D6 M.D. every two levels after the first.', 0),
('creature', 'true-inca', 'Lightning Bolt (Illapa Inca)', '1D4 M.D. per level of experience', 1, '500 feet (152 m)', 'Illapa patron only.', 1),
('creature', 'pucara-red-giant', 'Telekinetic Stone Missile', '4D6 M.D.', 1, '1000 feet (305 m)', '+3 to strike. +1D6 M.D. at levels 3, 5, 7, 9, 11, 13 and 15. 4 I.S.P. and one melee action per shot. With a called shot the rock may come from anywhere within 30 feet (9.1 m) of the giant, including behind the target (no dodge).', 0),
('creature', 'arkhon', 'Bite', '2D6 S.D.C.', 0, NULL, NULL, 0),
('creature', 'arkhon', 'Claws', '+1D6 S.D.C.', 0, NULL, 'Added to the damage of hand to hand punches and kicks.', 1),
('creature', 'men-rall', 'Electrical Discharge', '2D6 M.D.', 1, '200 feet (61 m)', 'Or 1D6 to 1D6x10 S.D.C., set in 1D6 steps. +1D6 M.D. every two levels after the first (3D6 M.D. at level three, 4D6 M.D. at level five).', 0),
('creature', 'blood-lizard', 'Claws or Slashing Tail', '1D6 M.D. plus Supernatural P.S. damage', 1, NULL, NULL, 0),
('creature', 'blood-lizard', 'Bite', '4D6 M.D.', 1, NULL, NULL, 1),
('creature', 'blood-lizard', 'Tearing Leap Kick', '2D6 M.D. plus Supernatural P.S. damage', 1, NULL, NULL, 2),
('creature', 'serpentoid', 'Bite', '2D4 S.D.C.', 0, NULL, '2D6 M.D. when the force field is activated.', 0),
('creature', 'serpentoid', 'Venom', '1D6 direct to Hit Points per melee for 4D4 melees', 0, NULL, 'Save vs lethal poison each melee; a successful save means no damage that round.', 1),
('creature', 'serpentoid', 'Charged Psychic Venom', '4D6 M.D. per melee round for 1D6 melee rounds', 1, NULL, '15 I.S.P. per dose. Against S.D.C. beings it is 2D6 to Hit Points instead. Save vs psionics every round; a save cuts that round''s damage to 1 point.', 2),
('creature', 'mutant-capybara', 'Bite', '2D4 S.D.C.', 0, NULL, NULL, 0),
('creature', 'mutant-capybara', 'Power Punch', '1D4 M.D.', 1, NULL, 'Counts as two attacks.', 1),
('creature', 'mutant-capybara', 'Psi-Wave', '1D4 M.D. +1 M.D. per level of experience', 1, 'Cone covering up to 20 feet (6.1 m), +3 feet (0.9 m) per additional level', '10 I.S.P. per attack, +2 to strike; dodging needs a 14 or higher. Knocks down most beings or vehicles under 2 tons. Living targets save vs psionics or are stunned 1D4 rounds (lose initiative and one attack, -1 strike, parry and dodge, -10% on skills).', 2),
('creature', 'equinoid', 'Psi-Bow', '4D6 M.D. +1 M.D. per level of experience', 1, '300 feet (91.5 m) +40 feet (12 m) per level', '15 I.S.P. to create; +2 to strike plus Archery and Targeting bonuses.', 0),
('creature', 'equinoid', 'Punch', '1D4 M.D. plus P.S. bonus', 1, NULL, 'M.D. only while the force field is up; the same figure in S.D.C. without it.', 1),
('creature', 'equinoid', 'Foreleg Kick', '2D4 M.D. plus P.S. bonus', 1, NULL, 'M.D. only while the force field is up; the same figure in S.D.C. without it.', 2),
('creature', 'equinoid', 'Hind Legs Kick', '3D6 M.D. plus P.S. bonus', 1, NULL, 'M.D. only while the force field is up; the same figure in S.D.C. without it.', 3),
('creature', 'condoroid', 'Beak', '2D4 S.D.C.', 0, NULL, NULL, 0),
('creature', 'falconoid', 'Beak', '1D6 S.D.C.', 0, NULL, NULL, 0),
('creature', 'falconoid', 'Psi-Blast', '2D6 M.D.', 1, '2000 feet (610 m)', '6 I.S.P. per blast, +3 to strike. +1D6 M.D. at levels 3, 5, 7, 9, 11 and 13. Any living target struck, even through armor, saves vs psionics or takes 2D6 S.D.C. (M.D.C. if supernatural) and is stunned 1D4 rounds (-1 initiative, strike, parry and dodge, -10% on skills).', 1),
('creature', 'neo-human', 'Touch of Death', '1D4x10 S.D.C. or M.D.C.', 1, 'Touch', '15 I.S.P. Passes body armor but not power armor or vehicle armor. Save vs psionics: on a save the victim takes 1D6 S.D.C. (or 2D6 M.D.) only; on a failure also save vs lethal poison or fall unconscious 1D4 melee rounds.', 0),
('creature', 'neo-human', 'Hyper-Telekinesis (thrown M.D.C. object)', '1D4 M.D. per 200 lbs. (90 kg) of weight or fraction thereof', 1, '100 feet (30.5 m) +50 feet (15.2 m) per level', '50 I.S.P. to activate. A one-ton M.D.C. object does 1D4x10 M.D.', 1),
('creature', 'amaki-stone-man', 'Restrained Punch', '1D4 S.D.C. plus P.S. bonus', 0, NULL, NULL, 0),
('creature', 'amaki-stone-man', 'Full Strength Punch', '4D6 S.D.C. plus P.S. bonus', 0, NULL, NULL, 1),
('creature', 'amaki-stone-man', 'Power Punch', '1D6 M.D.', 1, NULL, 'Counts as two attacks.', 2);
INSERT INTO data_script_runs (filename) VALUES ('~087-south-america-2-race-creatures.sql');
